function read(p,f){try{return JSON.parse(fs.readFileSync(p,"utf8"))}catch{return f}}function write(p,v){fs.writeFileSync(p,JSON.stringify(v,null,2))}function send(res,code,body){res.writeHead(code,{"content-type":"application/json; charset=utf-8","access-control-allow-origin":"*","access-control-allow-methods":"GET,POST,OPTIONS","access-control-allow-headers":"content-type"});res.end(JSON.stringify(body,null,2))}function body(req){return new Promise(r=>{let d="";req.on("data",c=>d+=c);req.on("end",()=>{try{r(d?JSON.parse(d):{})}catch{r({})}})})}function aid(){return `att_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`}function attempts(){return read(ATT,[])}
function markEvidence(a,node){if(!node||node.terminal)return; a.evidence_seen=a.evidence_seen||[]; for(const e of node.evidence||[]){if(!a.evidence_seen.find(x=>x.node_id===node.id&&x.evidence_id===e.id)){a.evidence_seen.push({node_id:node.id,scene:node.scene,evidence_id:e.id,label:e.label,type:e.type,basis:e.basis,teaches:e.teaches});}}}
function inspectedIds(a,nodeId){return new Set((a.evidence_inspections||[]).filter(x=>x.node_id===nodeId).map(x=>x.evidence_id))}
function missedForNode(a,nodeId){const ins=inspectedIds(a,nodeId);return (a.evidence_seen||[]).filter(x=>x.node_id===nodeId&&!ins.has(x.evidence_id))}
function autopsy(a,n){const tags={};const strengths=[],weak=[];for(const c of a.choices){for(const t of c.tags||[])tags[t]=(tags[t]||0)+1;if(c.score>0)strengths.push(c.label);if(c.score<0)weak.push(c.label)}const timeline=a.choices.map((c,i)=>({move:i+1,scene:c.scene,label:c.label,score:c.score,tags:c.tags||[],basis:c.basis||[],consequence:c.consequence||null,missed_evidence:missedForNode(a,c.node_id).map(e=>({label:e.label,type:e.type,basis:e.basis}))}));const missed=[];for(const e of a.evidence_seen||[]){if(!inspectedIds(a,e.node_id).has(e.evidence_id))missed.push(e)}return{profile:n.profile,result:n.result,diagnosis:n.diagnosis,scar:n.scar,score_total:a.score_total,top_mistakes:Object.entries(tags).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([tag,count])=>({tag,count})),strengths:strengths.slice(-5),weak_choices:weak.slice(-5),timeline,missed_evidence:missed.slice(0,18),inspected_evidence:a.evidence_inspections||[],evidence_basis:scenario.source_logic}}
function catalog(){return [scenario,{id:"s02-headline-poison",title:"Headline Poison",status:"locked",module:"second-stake",scenario_number:2,scar:"A story can be true and still not pay the contract."},{id:"s03-liquidity-mirage",title:"The Liquidity Mirage",status:"locked",module:"second-stake",scenario_number:3,scar:"A price you cannot exit is decoration."}]}
http.createServer(async(req,res)=>{const url=new URL(req.url,`http://${req.headers.host}`);if(req.method==="OPTIONS")return send(res,204,{});if(url.pathname==="/health")return send(res,200,{ok:true,layer:"The Forge",build:BUILD,status:"online",active_scenario:scenario.id,game_mode:"tracked_evidence_casefile"});if(url.pathname==="/api/catalog")return send(res,200,{ok:true,build:BUILD,catalog:{module:"second-stake",active_scenario:scenario.id,doctrine:"inspect evidence, decide, autopsy the trail"}});if(url.pathname==="/api/scenarios")return send(res,200,{ok:true,build:BUILD,scenarios:catalog().map(s=>({id:s.id,title:s.title,subtitle:s.subtitle||null,status:s.status,scar:s.scar,module:s.module,scenario_number:s.scenario_number,format:s.format||"locked"}))});if(req.method==="GET"&&url.pathname.startsWith("/api/scenarios/")){const sid=decodeURIComponent(url.pathname.split("/").pop());if(sid!==scenario.id&&sid!==scenario.legacy_id)return send(res,423,{ok:false,error:"Scenario locked"});return send(res,200,{ok:true,build:BUILD,scenario})}if(req.method==="POST"&&url.pathname==="/api/attempts"){const b=await body(req);if(b.scenario_id&&b.scenario_id!==scenario.id&&b.scenario_id!==scenario.legacy_id)return send(res,404,{ok:false,error:"Playable scenario not found"});const start=nodeMap().start;const a={attempt_id:aid(),scenario_id:scenario.id,scenario_title:scenario.title,module:scenario.module,status:"in_progress",started_at:new Date().toISOString(),completed_at:null,current_node_id:"start",choices:[],evidence_seen:[],evidence_inspections:[],score_total:0,outcome:null,scar_unlocked:null};markEvidence(a,start);const list=attempts();list.unshift(a);write(ATT,list);return send(res,201,{ok:true,build:BUILD,attempt:a,node:start,scenario_summary:{id:scenario.id,title:scenario.title,scar:scenario.scar,scenario_number:1,format:scenario.format}})}if(req.method==="POST"&&url.pathname.match(/^\/api\/attempts\/[^/]+\/evidence$/)){const attemptId=url.pathname.split("/")[3],b=await body(req),list=attempts(),a=list.find(x=>x.attempt_id===attemptId);if(!a)return send(res,404,{ok:false,error:"Attempt not found"});const node=nodeMap()[b.node_id||a.current_node_id];const e=(node?.evidence||[]).find(x=>x.id===b.evidence_id);if(!node||!e)return send(res,400,{ok:false,error:"Evidence not valid for current node"});a.evidence_inspections=a.evidence_inspections||[];if(!a.evidence_inspections.find(x=>x.node_id===node.id&&x.evidence_id===e.id)){a.evidence_inspections.push({at:new Date().toISOString(),node_id:node.id,scene:node.scene,evidence_id:e.id,label:e.label,type:e.type,basis:e.basis,teaches:e.teaches});}write(ATT,list);return send(res,200,{ok:true,build:BUILD,attempt:a,evidence:e,inspected:true})}if(req.method==="POST"&&url.pathname.match(/^\/api\/attempts\/[^/]+\/choice$/)){const attemptId=url.pathname.split("/")[3],b=await body(req),list=attempts(),a=list.find(x=>x.attempt_id===attemptId);if(!a)return send(res,404,{ok:false,error:"Attempt not found"});if(a.status==="complete")return send(res,409,{ok:false,error:"Attempt already complete",attempt:a});const m=nodeMap(),node=m[b.node_id||a.current_node_id],c=(node?.choices||[]).find(x=>x.id===b.choice_id);if(!c)return send(res,400,{ok:false,error:"Choice not valid"});a.choices.push({at:new Date().toISOString(),node_id:node.id,scene:node.scene,choice_id:c.id,label:c.label,next_node_id:c.next,score:c.score||0,tags:c.tags||[],basis:c.basis||[],consequence:c.consequence||null,inspected_before_choice:[...inspectedIds(a,node.id)]});a.score_total+=(c.score||0);a.current_node_id=c.next;let next=m[c.next];markEvidence(a,next);if(next?.terminal){const out=autopsy(a,next);a.status="complete";a.completed_at=new Date().toISOString();a.outcome=out;a.scar_unlocked=out.scar;a.top_mistakes=out.top_mistakes;a.strengths=out.strengths;next={...next,outcome:out}}write(ATT,list);return send(res,200,{ok:true,build:BUILD,attempt:a,node:next,complete:a.status==="complete",scar_unlocked:a.scar_unlocked})}if(req.method==="GET"&&url.pathname==="/api/attempts")return send(res,200,{ok:true,build:BUILD,attempts:attempts().slice(0,80).map(a=>({attempt_id:a.attempt_id,scenario_id:a.scenario_id,scenario_title:a.scenario_title,status:a.status,started_at:a.started_at,completed_at:a.completed_at,choices_count:a.choices.length,evidence_inspections_count:(a.evidence_inspections||[]).length,score_total:a.score_total,scar_unlocked:a.scar_unlocked,profile:a.outcome?.profile||null}))});if(req.method==="GET"&&url.pathname==="/api/progress"){const list=attempts(),done=list.filter(a=>a.status==="complete");return send(res,200,{ok:true,build:BUILD,progress:{total_attempts:list.length,completed_attempts:done.length,scars_unlocked:new Set(done.map(a=>a.scar_unlocked).filter(Boolean)).size,evidence_inspections:list.reduce((n,a)=>n+(a.evidence_inspections||[]).length,0)}})}return send(res,404,{ok:false,error:"Route not found",build:BUILD})}).listen(PORT,"127.0.0.1",()=>console.log(`The Forge ${BUILD} running on ${PORT}`));
JS
cat > /etc/systemd/system/oddsxray-forge.service <<'UNIT'
[Unit]
Description=Odds X-Ray Forge API
After=network.target
[Service]
WorkingDirectory=/opt/oddsxray-forge
ExecStart=/usr/bin/node /opt/oddsxray-forge/server.js
Restart=always
RestartSec=3
Environment=PORT=3001
[Install]
WantedBy=multi-user.target
UNIT
cat > /etc/nginx/sites-available/oddsxray-forge <<'NGINX'
server { listen 80; server_name forge.oddsxray.com 209.74.83.238; location / { proxy_pass http://127.0.0.1:3001; proxy_http_version 1.1; proxy_set_header Host $host; proxy_set_header X-Real-IP $remote_addr; } }
NGINX
ln -sf /etc/nginx/sites-available/oddsxray-forge /etc/nginx/sites-enabled/oddsxray-forge
if [ -e /etc/nginx/sites-enabled/default ]; then mv /etc/nginx/sites-enabled/default /etc/nginx/sites-enabled/default.disabled 2>/dev/null || true; fi
nginx -t
systemctl daemon-reload
systemctl enable oddsxray-forge >/dev/null 2>&1 || true
systemctl restart oddsxray-forge
systemctl reload nginx
systemctl disable --now odx-forge-update.timer >/dev/null 2>&1 || true
echo "FORGE-007A installed: tracked evidence casefile engine."
curl -s http://127.0.0.1:3001/health
